    title Mobile App Backend - Serverless Deployment

    Deployment_Node(cloud_region, "Cloud Provider Region", "AWS, Azure, or GCP", "The geographical region where the application is deployed.") {
        Deployment_Node(api_gateway, "API Gateway", "AWS API Gateway, Azure API Management, or Google Cloud API Gateway", "Handles incoming requests and routes them to the appropriate Lambda functions.") {
            Container(api, "API", "REST", "Provides a RESTful API for the mobile application.")
        }

        Deployment_Node(lambda_functions, "Lambda Functions", "AWS Lambda, Azure Functions, or Google Cloud Functions", "Serverless functions that implement the application logic.") {
            Component(auth, "Authentication", "Node.js", "Handles user authentication and authorization.")
            Component(data_access, "Data Access", "Python", "Interacts with the database.")
        }

        Deployment_Node(database, "Database", "DynamoDB, Cosmos DB, or Cloud Firestore", "Stores application data.") {
            ContainerDb(db, "Database", "NoSQL", "Stores user data, application settings, and other persistent data.")
        }
    }

    Rel(api, lambda_functions, "Routes requests to", "HTTPS")
    UpdateRelStyle(api, lambda_functions, $offsetY="-40")
    Rel(lambda_functions, database, "Reads from and writes to", "Database SDK")
    UpdateRelStyle(lambda_functions, database, $offsetY="-40")
    Rel(cloud_region, api_gateway, "Hosts")
    Rel(cloud_region, lambda_functions, "Hosts")
