    title Real-time Chat Application Deployment

    Deployment_Node(regionA, "Region A", "AWS US-East-1") {
        Deployment_Node(chatServerA, "Chat Server A", "Ubuntu 20.04") {
            Container(chatAppA, "Chat Application", "Node.js, Socket.IO", "Handles chat messages and user connections in Region A")
            ContainerDb(redisA, "Redis Cache", "Redis 6.x", "Stores active user sessions and chat history for Region A")
        }
    }

    Deployment_Node(regionB, "Region B", "AWS EU-West-1") {
        Deployment_Node(chatServerB, "Chat Server B", "Ubuntu 20.04") {
            Container(chatAppB, "Chat Application", "Node.js, Socket.IO", "Handles chat messages and user connections in Region B")
            ContainerDb(redisB, "Redis Cache", "Redis 6.x", "Stores active user sessions and chat history for Region B")
        }
    }

    Person(userA, "User A", "A user in Region A")
    Person(userB, "User B", "A user in Region B")

    Rel(userA, chatServerA, "Connects via WebSocket", "HTTPS")
    Rel(userB, chatServerB, "Connects via WebSocket", "HTTPS")

    Rel(chatAppA, redisA, "Reads/Writes to", "Redis Protocol")
    Rel(chatAppB, redisB, "Reads/Writes to", "Redis Protocol")

    UpdateRelStyle(userA, chatServerA, $offsetY="-40")
    UpdateRelStyle(userB, chatServerB, $offsetY="-40")
    UpdateRelStyle(chatAppA, redisA, $offsetY="-20")
    UpdateRelStyle(chatAppB, redisB, $offsetY="-20")

